// ReSharper disable StringLiteralTypo
namespace Atc.Rest.Api.SourceGenerator.Tests.Generators;

/// <summary>
/// End-to-end error-body matrix: the generated server runs on Kestrel, and every generated client calls it over
/// HTTP - the C# EndpointPerOperation client with each <c>errorResponseFormat</c> (Custom with the Monta sample's
/// <c>customErrorResponseModel</c>), the C# TypedClient in both result styles, and the TypeScript Fetch and Axios
/// clients generated by the CLI executable. Every cell gets a verdict from the documented error contract
/// (Working with Error Responses), applied to what was observed on the wire - no expected value is written down
/// per cell.
/// </summary>
/// <remarks>
/// Verdicts: <c>pass</c> - the client exposes what the contract says; <c>lossy</c> - the client does what the
/// documentation says, without an exception, but the typed value cannot hold some fields of the body (named in the
/// cell; they stay in the raw body) - for example the custom error model reading a ProblemDetails; <c>fail</c> - the
/// contract is broken (wrong status, accessor, type, arm or value, or an exception); <c>platform</c> - the runtime
/// rejects the response before any client code runs.
/// </remarks>
public partial class ErrorResponseBodyRuntimeTests
{
    private const string VerdictPass = "pass";
    private const string VerdictLossy = "lossy";
    private const string VerdictFail = "fail";
    private const string VerdictPlatform = "platform";
    private const string CustomModel = "ErrorResponse (custom)";
    private const string DefaultModel = "ErrorResponse";

    /// <summary>
    /// The Monta sample's custom error model (sample/ThirdParty-EPO-Clients/MontaClient/.atc-rest-api-client), under
    /// its own name.
    /// </summary>
    private const string MontaCustomMarker = """
        {
          "generationMode": "EndpointPerOperation",
          "errorResponseFormat": "Custom",
          "customErrorResponseModel": {
            "name": "ErrorResponse",
            "description": "Represents an error response from the Monta API.",
            "schema": {
              "status": { "dataType": "string?", "description": "Gets or sets the status of the error." },
              "message": { "dataType": "string?", "description": "Gets or sets the error message." },
              "readableMessage": { "dataType": "string?", "description": "Gets or sets the readable message." },
              "errorCode": { "dataType": "string?", "description": "Gets or sets the error code." },
              "context": { "dataType": "object?", "description": "Gets or sets the context information." }
            }
          }
        }
        """;

    internal static readonly (string OperationId, string Label, string Spec)[] MatrixDeclarations =
    [
        ("setAllNone", "Nothing declared", "responses: '404': { description: Not Found }"),
        ("setAllJsonProblem", "application/json - a model", "content: { application/json: { schema: { $ref: '#/components/schemas/ApiProblem' } } }"),
        ("setAllJsonString", "application/json - a string", "content: { application/json: { schema: { type: string } } }"),
        ("setAllTextPlain", "text/plain - a string", "content: { text/plain: { schema: { type: string } } }"),
        ("setAllFrameworkProblem", "application/problem+json - ProblemDetails", "content: { application/problem+json: { schema: { $ref: '#/components/schemas/ProblemDetails' } } }"),
        ("setProblemJson", "application/problem+json - a model (400/404/409/422)", "content: { application/problem+json: { schema: { $ref: '#/components/schemas/ApiProblem' } } }"),
        ("setRefResponse", "$ref to components/responses (404/422)", "'404': { $ref: '#/components/responses/NotFound' } - application/json RefOnlyError"),
    ];

    private static readonly int[] NamedArmStatuses = [400, 401, 403, 404, 409, 422, 429];

    internal static readonly (string Id, string Group, string Label, string? Format)[] MatrixClients =
    [
        ("cs-epo-ProblemDetails", "C# EndpointPerOperation", "errorResponseFormat: ProblemDetails", "ProblemDetails"),
        ("cs-epo-PlainText", "C# EndpointPerOperation", "errorResponseFormat: PlainText", "PlainText"),
        ("cs-epo-PlainTextOnly", "C# EndpointPerOperation", "errorResponseFormat: PlainTextOnly", "PlainTextOnly"),
        ("cs-epo-Custom", "C# EndpointPerOperation", "errorResponseFormat: Custom (Monta ErrorResponse)", "Custom"),
        ("cs-typed-Throw", "C# TypedClient", "typedClientResultStyle: Throw", null),
        ("cs-typed-Result", "C# TypedClient", "typedClientResultStyle: Result", null),
        ("ts-fetch", "TypeScript", "Fetch client", null),
        ("ts-axios", "TypeScript", "Axios client", null),
    ];

    /// <summary>
    /// Every generated client, called over HTTP against the generated server, reads every error the server writes
    /// without breaking the documented contract (no <c>fail</c> verdict in the matrix).
    /// </summary>
    [Fact]
    [Trait("Category", "TypeScriptToolchain")]
    public async Task EndToEnd_EveryClientReadsWhatTheServerWrites()
    {
        if (!IsNodeAvailable(out var reason))
        {
            if (string.Equals(Environment.GetEnvironmentVariable("CI"), "true", StringComparison.OrdinalIgnoreCase))
            {
                Assert.Fail(reason + " (running under CI where the end-to-end matrix is required)");
            }

            Assert.Skip(reason);
        }

        var matrix = await CollectEndToEndMatrixAsync();
        if (Environment.GetEnvironmentVariable("ERRORBODY_E2E_JSON") is { Length: > 0 } dumpPath)
        {
            await File.WriteAllTextAsync(dumpPath, matrix.ToJsonString(), TestContext.Current.CancellationToken);
        }

        var failures = FailingCells(matrix);
        Assert.True(failures.Count == 0, $"{failures.Count} failing cells:\n" + string.Join("\n", failures.Take(80)));
    }

    /// <summary>
    /// Writes the matrix as <c>issues/return-body-report.json</c> and renders <c>issues/return-body-report.html</c>
    /// from <c>Generators/ErrorBodyReport.template.html</c>.
    /// </summary>
    [Fact(Explicit = true)]
    public async Task Report_EndToEndErrorBodyMatrix()
    {
        Assert.True(IsNodeAvailable(out var reason), reason);

        var matrix = await CollectEndToEndMatrixAsync();

        var root = FindRepositoryRoot();
        var issues = Path.Combine(root, "issues");
        Directory.CreateDirectory(issues);

        // Hand-written context shown next to the data: the 3.0 readiness notes, and the independent review's findings.
        foreach (var (key, file) in ((string, string)[])[("readiness", "return-body-readiness.html"), ("review", "return-body-review.html")])
        {
            var path = Path.Combine(issues, file);
            if (File.Exists(path))
            {
                matrix[key] = await File.ReadAllTextAsync(path, TestContext.Current.CancellationToken);
            }
        }

        var json = matrix.ToJsonString(new JsonSerializerOptions { WriteIndented = true });
        await File.WriteAllTextAsync(Path.Combine(issues, "return-body-report.json"), json, TestContext.Current.CancellationToken);

        var template = await File.ReadAllTextAsync(
            Path.Combine(root, "test", "Atc.Rest.Api.SourceGenerator.Tests", "Generators", "ErrorBodyReport.template.html"),
            TestContext.Current.CancellationToken);
        var html = template.Replace("/*__REPORT_DATA__*/null", matrix.ToJsonString().Replace("</", "<\\/", StringComparison.Ordinal), StringComparison.Ordinal);
        await File.WriteAllTextAsync(Path.Combine(issues, "return-body-report.html"), html, TestContext.Current.CancellationToken);
    }

    /// <summary>
    /// A custom error model named like a schema of the specification (the Monta sample's <c>ErrorResponse</c> next
    /// to the spec's own <c>ErrorResponse</c>): the spec's model keeps its type for the <c>default</c> response - the
    /// custom one used to shadow it through the root namespace - and the custom model's accessor reads a body that
    /// does not fit it (a ProblemDetails' numeric <c>status</c> in its string property) instead of throwing.
    /// </summary>
    [Fact]
    public async Task CustomErrorModel_NamedLikeASpecSchema_NeitherShadowsItNorThrows()
    {
        var sources = Generate(new ApiClientGenerator(), ".atc-rest-api-client", MontaCustomMarker, includeMinimalApi: false, DefaultOnlyYaml);
        Assert.Contains(sources, s => s.Source.Contains("namespace ErrorBodies.Generated.CustomErrors;", StringComparison.Ordinal));

        sources.Add(("Probe.cs", DefaultOnlyProbeSource));
        var assembly = CompilationVerificationHarness.EmitAndLoad(sources);
        var probe = assembly.GetType("ErrorBodies.RuntimeTest.Probe", throwOnError: true)!;
        var rows = await (Task<List<string>>)probe.GetMethod("RunAsync")!.Invoke(null, [])!;
        var report = string.Join("\n", rows);

        Assert.True(!report.Contains("THROWS", StringComparison.Ordinal), report);

        // The spec's ErrorResponse (code + message) for the default response.
        Assert.Contains(rows, r => r.StartsWith("jsonDefault/418: 418 IsDefaultError DefaultErrorContent => ErrorResponse {\"Code\":\"E418\"", StringComparison.Ordinal));

        // The custom model, read leniently from a ProblemDetails.
        Assert.Contains(rows, r => r.StartsWith("problemDefault/404: 404 IsNotFound NotFoundContent => ErrorResponse {\"status\":\"404\"", StringComparison.Ordinal));
    }

    /// <summary>
    /// Negative control for the matrix: every verdict rule fails a regressed result - a lost or changed value, a
    /// wrong accessor, arm or field - so a <c>pass</c> in the report is evidence, not the absence of a check.
    /// </summary>
    [Fact]
    public void MatrixVerdicts_FailRegressedResults()
    {
        const string problem404 = """{"type":"t","title":"Not Found","status":404,"detail":"404 message from handler"}""";
        var noneCase = new ProbeCase("setAllNone", "AllNone", "s404", ValidReason, IsPut: true);
        var noneWire = new WireResult(noneCase.Name, 404, "application/problem+json", problem404);
        var stringCase = new ProbeCase("setAllJsonString", "AllJsonString", "s404", ValidReason, IsPut: true);
        var stringWire = new WireResult(stringCase.Name, 404, "application/json", "\"404 message from handler\"");
        var emptyStringCase = new ProbeCase("setAllJsonString", "AllJsonString", "s404-empty", ValidReason, IsPut: true);
        var emptyStringWire = new WireResult(emptyStringCase.Name, 404, "application/problem+json", """{"type":"t","title":"Not Found","status":404}""");
        var defaultCase = new ProbeCase("getDefaultError", "DefaultError", "d404", Reason: null, IsPut: false);
        var defaultWire = new WireResult(defaultCase.Name, 404, "application/json", """{"code":"c404","message":"404 default from handler"}""");
        var undeclaredCase = new ProbeCase("getFault", "Faults", "throw-not-implemented", Reason: null, IsPut: false);
        var undeclaredWire = new WireResult(undeclaredCase.Name, 501, "application/problem+json", """{"title":"Not Implemented","status":501}""");

        string EndpointPerOperation(
            ProbeCase probeCase,
            WireResult wire,
            string format,
            string accessor,
            string content = "")
            => (string)EndpointPerOperationVerdict(probeCase, wire, format, ["case", wire.Status.ToString(CultureInfo.InvariantCulture), "False", "-", accessor, content])["verdict"]!;

        // Positive controls: the same rules pass the correct result.
        Assert.Equal(VerdictPass, EndpointPerOperation(noneCase, noneWire, "ProblemDetails", """NotFoundContent => ProblemDetails {"Type":"t","Title":"Not Found","Status":404,"Detail":"404 message from handler","Instance":null,"Extensions":{}}"""));
        Assert.Equal(VerdictPass, EndpointPerOperation(stringCase, stringWire, "ProblemDetails", "NotFoundContent => string \"404 message from handler\""));
        Assert.Equal(VerdictPass, EndpointPerOperation(defaultCase, defaultWire, "ProblemDetails", """DefaultErrorContent => ErrorResponse {"Code":"c404","Message":"404 default from handler"}"""));

        // EndpointPerOperation: a changed field, a lost string, the ProblemDetails' JSON text as a string, a wrong
        // custom field, the default body on the status's accessor, an undeclared status without its raw body.
        Assert.Equal(VerdictFail, EndpointPerOperation(noneCase, noneWire, "ProblemDetails", """NotFoundContent => ProblemDetails {"Type":"t","Title":"Not Found","Status":404,"Detail":null,"Instance":null,"Extensions":{}}"""));
        Assert.Equal(VerdictFail, EndpointPerOperation(stringCase, stringWire, "ProblemDetails", "NotFoundContent => string \"404 message\""));
        Assert.Equal(VerdictFail, EndpointPerOperation(emptyStringCase, emptyStringWire, "ProblemDetails", "NotFoundContent => string \"{\\u0022type\\u0022:\\u0022t\\u0022}\""));
        Assert.Equal(VerdictFail, EndpointPerOperation(noneCase, noneWire, "Custom", """NotFoundContent => ErrorResponse {"status":"999","message":null,"readableMessage":null,"errorCode":null,"context":null}"""));
        Assert.Equal(VerdictFail, EndpointPerOperation(defaultCase, defaultWire, "ProblemDetails", """NotFoundContent => ProblemDetails {"Type":null,"Title":null,"Status":404,"Detail":null,"Instance":null,"Extensions":{}}"""));
        Assert.Equal(VerdictFail, EndpointPerOperation(undeclaredCase, undeclaredWire, "ProblemDetails", "(none)", content: "{}"));
        Assert.Equal(VerdictPass, EndpointPerOperation(undeclaredCase, undeclaredWire, "ProblemDetails", "(none)", content: undeclaredWire.Body));

        // TypeScript: the arm the spec gives, the generated union's named arms, and the body's fields.
        string[] allArms = ["noContent", "badRequest", "unauthorized", "forbidden", "notFound", "conflict", "unprocessableEntity", "tooManyRequests", "clientError", "serverError", "parseError"];
        JsonObject TsResult(
            string arm,
            string? detail)
            => new()
            {
                ["arm"] = arm,
                ["httpStatus"] = 404,
                ["statusText"] = "Not Found",
                ["errorClass"] = "ApiError",
                ["errorStatus"] = 404,
                ["message"] = "404 message from handler",
                ["detail"] = detail,
                ["title"] = "Not Found",
                ["problemType"] = "t",
                ["instance"] = null,
                ["body"] = JsonNode.Parse(problem404),
            };

        Assert.Equal(VerdictPass, (string)TypeScriptVerdict(noneCase, noneWire, TsResult("notFound", "404 message from handler"), allArms)["verdict"]!);
        Assert.Equal(VerdictFail, (string)TypeScriptVerdict(noneCase, noneWire, TsResult("clientError", "404 message from handler"), allArms)["verdict"]!);
        Assert.Equal(VerdictFail, (string)TypeScriptVerdict(noneCase, noneWire, TsResult("notFound", "404 message from handler"), [.. allArms.Where(a => a != "notFound")])["verdict"]!);
        Assert.Equal(VerdictFail, (string)TypeScriptVerdict(noneCase, noneWire, TsResult("notFound", detail: null), allArms)["verdict"]!);

        string TsVerdict(Action<JsonObject> regress)
        {
            var result = TsResult("notFound", "404 message from handler");
            regress(result);
            return (string)TypeScriptVerdict(noneCase, noneWire, result, allArms)["verdict"]!;
        }

        Assert.Equal(VerdictFail, TsVerdict(r => r["body"] = JsonNode.Parse("""{"status":404}""")));
        Assert.Equal(VerdictFail, TsVerdict(r => r["body"] = "__undefined__"));
        Assert.Equal(VerdictFail, TsVerdict(r => r["message"] = "Not Found"));
        Assert.Equal(VerdictFail, TsVerdict(r => r["errorStatus"] = 500));
        Assert.Equal(VerdictFail, TsVerdict(r => r["errorClass"] = "Error"));

        var validationCase = new ProbeCase("setAllNone", "AllNone", "ok", TooLongReason, IsPut: true);
        var validationWire = new WireResult(validationCase.Name, 400, "application/problem+json", """{"title":"One or more validation errors occurred.","status":400,"errors":{"reason":["too long"]}}""");
        string ValidationTs(JsonNode errors)
            => (string)TypeScriptVerdict(
                validationCase,
                validationWire,
                new JsonObject
                {
                    ["arm"] = "badRequest",
                    ["httpStatus"] = 400,
                    ["statusText"] = "Bad Request",
                    ["errorClass"] = "ValidationError",
                    ["errorStatus"] = 400,
                    ["message"] = "One or more validation errors occurred.",
                    ["detail"] = null,
                    ["title"] = "One or more validation errors occurred.",
                    ["problemType"] = null,
                    ["instance"] = null,
                    ["body"] = JsonNode.Parse(validationWire.Body),
                    ["errors"] = errors,
                },
                allArms)["verdict"]!;
        Assert.Equal(VerdictPass, ValidationTs(JsonNode.Parse("""{"reason":["too long"]}""")!));
        Assert.Equal(VerdictFail, ValidationTs(new JsonObject()));

        var okCase = new ProbeCase("setAllNone", "AllNone", "ok", ValidReason, IsPut: true);
        var okWire = new WireResult(okCase.Name, 204, "(none)", "(empty)");
        Assert.Equal(VerdictPass, (string)TypeScriptVerdict(okCase, okWire, new JsonObject { ["arm"] = "noContent", ["httpStatus"] = 204 }, allArms)["verdict"]!);
        Assert.Equal(VerdictFail, (string)TypeScriptVerdict(okCase, okWire, new JsonObject { ["arm"] = "ok", ["httpStatus"] = 204 }, allArms)["verdict"]!);

        // EndpointPerOperation: the success accessor, IsSuccess on an error, and a lossy verdict names the lost fields.
        Assert.Equal(VerdictPass, (string)EndpointPerOperationVerdict(okCase, okWire, "ProblemDetails", ["case", "204", "True", "null", "IsNoContent (no content property)", string.Empty])["verdict"]!);
        Assert.Equal(VerdictFail, (string)EndpointPerOperationVerdict(okCase, okWire, "ProblemDetails", ["case", "204", "False", "null", "IsNoContent (no content property)", string.Empty])["verdict"]!);
        Assert.Equal(VerdictFail, (string)EndpointPerOperationVerdict(noneCase, noneWire, "ProblemDetails", ["case", "404", "True", "-", """NotFoundContent => ProblemDetails {"Type":"t","Title":"Not Found","Status":404,"Detail":"404 message from handler","Instance":null,"Extensions":{}}""", string.Empty])["verdict"]!);
        var customCell = EndpointPerOperationVerdict(noneCase, noneWire, "Custom", ["case", "404", "False", "-", """NotFoundContent => ErrorResponse {"status":"404","message":null,"readableMessage":null,"errorCode":null,"context":null}""", string.Empty]);
        Assert.Equal(VerdictLossy, (string)customCell["verdict"]!);
        Assert.Contains("type, title, detail", (string)customCell["why"]!, StringComparison.Ordinal);

        // Wire: the validation 400, the success body, a 4xx exception's ProblemDetails.
        Assert.Equal(VerdictPass, WireVerdict(validationCase, validationWire).Verdict);
        Assert.Equal(VerdictFail, WireVerdict(validationCase, validationWire with { Body = """{"title":"x","status":400}""" }).Verdict);
        Assert.Equal(VerdictPass, WireVerdict(okCase, okWire).Verdict);
        Assert.Equal(VerdictFail, WireVerdict(okCase, okWire with { Body = "{}" }).Verdict);
        var argumentCase = new ProbeCase("setProblemJson", "ProblemJson", "throw-argument", ValidReason, IsPut: true);
        Assert.Equal(VerdictPass, WireVerdict(argumentCase, new WireResult(argumentCase.Name, 400, "application/problem+json", """{"title":"Bad Request","status":400}""")).Verdict);
        Assert.Equal(VerdictFail, WireVerdict(argumentCase, new WireResult(argumentCase.Name, 400, "application/json", "\"argument rejected\"")).Verdict);

        // Wire: the default body, a 5xx exception's detail outside Development, Retry-After on a 429.
        Assert.Equal(VerdictFail, WireVerdict(defaultCase, defaultWire with { Body = """{"code":"c404"}""" }).Verdict);
        var throwCase = new ProbeCase("getFault", "Faults", "throw", Reason: null, IsPut: false);
        Assert.Equal(VerdictPass, WireVerdict(throwCase, new WireResult(throwCase.Name, 500, "application/problem+json", """{"title":"An error occurred","status":500}""")).Verdict);
        Assert.Equal(VerdictFail, WireVerdict(throwCase, new WireResult(throwCase.Name, 500, "application/problem+json", """{"title":"An error occurred","status":500,"detail":"boom from handler"}""")).Verdict);
        var tooManyCase = new ProbeCase("setAllJsonString", "AllJsonString", "s429", ValidReason, IsPut: true);
        Assert.Equal(VerdictPass, WireVerdict(tooManyCase, new WireResult(tooManyCase.Name, 429, "application/json", "\"429 message from handler\"", RetryAfter: "30")).Verdict);
        Assert.Equal(VerdictFail, WireVerdict(tooManyCase, new WireResult(tooManyCase.Name, 429, "application/json", "\"429 message from handler\"")).Verdict);

        // A body that is no JSON object: the ProblemDetails' Detail is the body; the custom model has nothing set.
        var xmlCase = new ProbeCase("getFault", "Faults", "stub-xml", Reason: null, IsPut: false);
        var xmlWire = new WireResult(xmlCase.Name, 503, "application/xml", "<error>down</error>");
        Assert.Equal(VerdictPass, EndpointPerOperation(xmlCase, xmlWire, "ProblemDetails", """ServiceUnavailableContent => ProblemDetails {"Type":"x","Title":"ServiceUnavailable","Status":503,"Detail":"<error>down</error>","Instance":null}"""));
        Assert.Equal(VerdictFail, EndpointPerOperation(xmlCase, xmlWire, "ProblemDetails", """ServiceUnavailableContent => ProblemDetails {"Type":"x","Title":"ServiceUnavailable","Status":503,"Detail":null,"Instance":null}"""));
        Assert.Equal(VerdictFail, EndpointPerOperation(xmlCase, xmlWire, "PlainText", "ServiceUnavailableContent => string \"\""));
        Assert.Equal(VerdictFail, EndpointPerOperation(xmlCase, xmlWire, "Custom", """ServiceUnavailableContent => ErrorResponse {"status":"503","message":null,"readableMessage":null,"errorCode":null,"context":null}"""));
        Assert.Equal(VerdictFail, WireVerdict(xmlCase, xmlWire).Verdict);

        // A handler's error factory: the ProblemDetails must carry the handler's value.
        var valueCase = new ProbeCase("getFault", "Faults", "error500", Reason: null, IsPut: false);
        Assert.Equal(VerdictPass, WireVerdict(valueCase, new WireResult(valueCase.Name, 500, "application/problem+json", """{"title":"InternalServerError","status":500,"detail":"500 problem from handler"}""")).Verdict);
        Assert.Equal(VerdictFail, WireVerdict(valueCase, new WireResult(valueCase.Name, 500, "application/problem+json", """{"title":"InternalServerError","status":500}""")).Verdict);

        // TypedClient Throw: the exception carries the status and the body.
        Assert.Equal(VerdictPass, (string)TypedClientVerdict(noneWire, throwStyle: true, ["case", $"HttpRequestException: HTTP 404 (Not Found): {problem404}"])["verdict"]!);
        Assert.Equal(VerdictFail, (string)TypedClientVerdict(noneWire, throwStyle: true, ["case", "HttpRequestException: HTTP 404 (Not Found): "])["verdict"]!);
        Assert.Equal(VerdictFail, (string)TypedClientVerdict(noneWire, throwStyle: true, ["case", "returned normally"])["verdict"]!);

        // TypedClient Result: an error has no parsed model.
        Assert.Equal(VerdictPass, (string)TypedClientVerdict(noneWire, throwStyle: false, ["case", $"404 IsSuccess=False Content={problem404} ContentObject=null"])["verdict"]!);
        Assert.Equal(VerdictFail, (string)TypedClientVerdict(noneWire, throwStyle: false, ["case", $"404 IsSuccess=False Content={problem404} ContentObject=Item"])["verdict"]!);
    }

    private static List<string> FailingCells(JsonObject matrix)
    {
        var failures = new List<string>();
        foreach (var node in matrix["cases"]!.AsArray())
        {
            var item = node!.AsObject();
            var name = (string)item["id"]!;
            if ((string?)item["wire"]!["verdict"] == VerdictFail)
            {
                failures.Add($"{name} [wire]: {(string?)item["wire"]!["why"]}");
            }

            foreach (var cell in item["clients"]!.AsObject())
            {
                if ((string?)cell.Value!["verdict"] == VerdictFail)
                {
                    failures.Add($"{name} [{cell.Key}]: {(string?)cell.Value["why"]} - {(string?)cell.Value["summary"]}");
                }
            }
        }

        return failures;
    }

    private static async Task<JsonObject> CollectEndToEndMatrixAsync()
    {
        var started = DateTimeOffset.Now;
        await using var host = await ErrorBodyHost.StartAsync();

        var matrixCases = host.Cases
            .Where(c => MatrixDeclarations.Any(d => d.OperationId == c.OperationId) || c.OperationId is "getFault" or "getDefaultError")
            .ToList();

        var wire = (await host.CaptureWireAsync()).ToDictionary(w => w.Case, StringComparer.Ordinal);

        var rows = new Dictionary<string, Dictionary<string, string[]>>(StringComparer.Ordinal);
        foreach (var client in MatrixClients.Where(c => c.Format is not null))
        {
            var marker = client.Format == "Custom" ? MontaCustomMarker : ClientOperationMarker(client.Format!);
            var generated = GenerateClientAssembly(marker, BuildOperationProbeSource);
            rows[client.Id] = (await RunProbeAsync(generated.Assembly, host.BaseAddress)).ToDictionary(r => r[0], StringComparer.Ordinal);
        }

        foreach (var style in TypedResultStyles)
        {
            var generated = GenerateClientAssembly(ClientTypedMarker(style), cases => BuildTypedProbeSource(cases, style));
            rows["cs-typed-" + style] = (await RunProbeAsync(generated.Assembly, host.BaseAddress)).ToDictionary(r => r[0], StringComparer.Ordinal);
        }

        var typeScript = RunTypeScriptClients(host.BaseAddress, matrixCases);

        var casesArray = new JsonArray();
        foreach (var probeCase in matrixCases)
        {
            var observed = wire[probeCase.Name];
            var wireVerdict = WireVerdict(probeCase, observed);
            var clients = new JsonObject();
            foreach (var client in MatrixClients)
            {
                JsonObject cell;
                if (client.Id.StartsWith("ts-", StringComparison.Ordinal))
                {
                    var (results, arms) = typeScript[client.Id];
                    cell = TypeScriptVerdict(probeCase, observed, results.GetValueOrDefault(probeCase.Name), arms.GetValueOrDefault(MethodKey(probeCase)) ?? []);
                }
                else if (client.Format is not null)
                {
                    cell = EndpointPerOperationVerdict(probeCase, observed, client.Format, rows[client.Id].GetValueOrDefault(probeCase.Name));
                }
                else
                {
                    cell = TypedClientVerdict(observed, client.Id.EndsWith("Throw", StringComparison.Ordinal), rows[client.Id].GetValueOrDefault(probeCase.Name));
                }

                clients[client.Id] = cell;
            }

            casesArray.Add(new JsonObject
            {
                ["id"] = probeCase.Name,
                ["operation"] = probeCase.OperationId,
                ["group"] = CaseGroup(probeCase),
                ["mode"] = probeCase.Mode,
                ["handler"] = HandlerCall(probeCase),
                ["status"] = observed.Status,
                ["wire"] = new JsonObject
                {
                    ["status"] = observed.Status,
                    ["contentType"] = observed.ContentType,
                    ["mediaType"] = observed.MediaType,
                    ["bodyKind"] = BodyKind(observed),
                    ["body"] = observed.Body,
                    ["retryAfter"] = observed.RetryAfter,
                    ["verdict"] = wireVerdict.Verdict,
                    ["why"] = wireVerdict.Why,
                },
                ["clients"] = clients,
            });
        }

        // Errors raised by the framework before any generated code runs: no generated client method reaches them.
        foreach (var observed in wire.Values.Where(w => w.Case.StartsWith("framework: ", StringComparison.Ordinal)))
        {
            var ok = string.Equals(observed.MediaType, "application/problem+json", StringComparison.Ordinal) &&
                     TryReadStatus(observed.Body, out var bodyStatus) && bodyStatus == observed.Status;
            casesArray.Add(new JsonObject
            {
                ["id"] = observed.Case,
                ["operation"] = "(framework)",
                ["group"] = "framework",
                ["mode"] = observed.Case["framework: ".Length..],
                ["handler"] = "no handler runs",
                ["status"] = observed.Status,
                ["wire"] = new JsonObject
                {
                    ["status"] = observed.Status,
                    ["contentType"] = observed.ContentType,
                    ["mediaType"] = observed.MediaType,
                    ["bodyKind"] = BodyKind(observed),
                    ["body"] = observed.Body,
                    ["retryAfter"] = observed.RetryAfter,
                    ["verdict"] = ok ? VerdictPass : VerdictFail,
                    ["why"] = ok ? "a ProblemDetails with the response status (host wiring)" : "expected a ProblemDetails with the response status",
                },
                ["clients"] = new JsonObject(),
            });
        }

        return new JsonObject
        {
            ["generatedAt"] = started.ToString("yyyy-MM-dd HH:mm:ss zzz", CultureInfo.InvariantCulture),
            ["durationSeconds"] = System.Math.Round((DateTimeOffset.Now - started).TotalSeconds, 1),
            ["provenance"] = Provenance(),
            ["declarations"] = new JsonArray([.. MatrixDeclarations.Select(d => (JsonNode)new JsonObject { ["id"] = d.OperationId, ["label"] = d.Label, ["spec"] = d.Spec })]),
            ["clients"] = new JsonArray([.. MatrixClients.Select(c => (JsonNode)new JsonObject { ["id"] = c.Id, ["group"] = c.Group, ["label"] = c.Label, ["format"] = c.Format })]),
            ["cases"] = casesArray,
        };
    }

    /// <summary>
    /// The scenario a case belongs to.
    /// </summary>
    private static string CaseGroup(ProbeCase probeCase)
        => probeCase switch
        {
            { Reason: TooLongReason } => "validation",
            _ when StubResponses.ContainsKey(probeCase.Mode) => "stub",
            { OperationId: "getFault" } => "fault",
            { OperationId: "getDefaultError" } => "default",
            _ when SweepStatus(probeCase.Mode) is not null => "sweep",
            { Mode: "ok" } => "success",
            _ when probeCase.Mode.StartsWith("throw", StringComparison.Ordinal) => "exception",
            _ => "handler",
        };

    private static string HandlerCall(ProbeCase probeCase)
    {
        if (probeCase.Reason == TooLongReason)
        {
            return "none - the ValidationFilter rejects the body";
        }

        if (StubResponses.TryGetValue(probeCase.Mode, out var stub))
        {
            return $"none - a stub answers: {stub.Description}";
        }

        if (SweepStatus(probeCase.Mode) is { } code)
        {
            var name = HttpStatusCodeHelper.ToEnumName(code);
            return probeCase.Mode.EndsWith("-empty", StringComparison.Ordinal) ? $"{name}()" : $"{name}(value)";
        }

        var factory = probeCase.Mode.Replace("-empty", string.Empty, StringComparison.Ordinal) switch
        {
            "bad" => "BadRequest",
            "missing" => "NotFound",
            "conflict" => "Conflict",
            "invalid" => "UnprocessableEntity",
            "error500" => "InternalServerError",
            "unavailable" => "ServiceUnavailable",
            _ => null,
        };

        if (factory is not null)
        {
            return probeCase.Mode.EndsWith("-empty", StringComparison.Ordinal) ? $"{factory}()" : $"{factory}(value)";
        }

        return probeCase.Mode switch
        {
            "ok" => "success",
            "throw" => "throws InvalidDataException",
            "throw-canceled" => "throws OperationCanceledException",
            "throw-unauthorized-access" => "throws UnauthorizedAccessException",
            "throw-argument-null" => "throws ArgumentNullException",
            "throw-bad-http-request" => "throws BadHttpRequestException(413)",
            "throw-argument" => "throws ArgumentException",
            "throw-invalid-operation" => "throws InvalidOperationException",
            "throw-timeout" => "throws TimeoutException",
            "throw-not-implemented" => "throws NotImplementedException",
            "error" => "Error(body) - the default response, 500",
            _ when probeCase.Mode.StartsWith('d') => $"Error(body, {probeCase.Mode[1..]}) - the default response",
            _ => probeCase.Mode,
        };
    }

    /// <summary>
    /// The status the case must produce: the handler's factory, the sweep code, or the exception mapping of
    /// Atc.Rest.MinimalApi (Working with Error Responses, "Exception → status mapping").
    /// </summary>
    private static int ExpectedStatus(ProbeCase probeCase)
    {
        if (probeCase.Reason == TooLongReason)
        {
            return 400;
        }

        if (StubResponses.TryGetValue(probeCase.Mode, out var stub))
        {
            return stub.Status;
        }

        if (SweepStatus(probeCase.Mode) is { } code)
        {
            return code;
        }

        var mode = probeCase.Mode.Replace("-empty", string.Empty, StringComparison.Ordinal);
        return mode switch
        {
            "ok" => probeCase.IsPut ? 204 : 200,
            "bad" or "throw-argument" => 400,
            "missing" => 404,
            "conflict" => 409,
            "invalid" => 422,
            "error" or "error500" or "throw" or "throw-invalid-operation" or "throw-unauthorized-access" or "throw-argument-null" => 500,
            "throw-bad-http-request" => 413,
            "throw-not-implemented" => 501,
            "unavailable" => 503,
            "throw-timeout" or "throw-canceled" => 504,
            _ when mode.StartsWith('d') => int.Parse(mode.AsSpan(1), NumberStyles.Integer, CultureInfo.InvariantCulture),
            _ => throw new InvalidOperationException($"No expected status for mode '{probeCase.Mode}'"),
        };
    }

    /// <summary>
    /// What the specification declares for an error status of an operation: <c>none</c> (declared without content),
    /// the body type, or <see langword="null"/> when the status is not declared.
    /// </summary>
    private static string? DeclaredError(
        string operationId,
        int status)
    {
        int[] codes;
        string type;
        switch (operationId)
        {
            case "setAllNone":
                (codes, type) = (AllErrorStatusCodes, "none");
                break;
            case "setAllFrameworkProblem":
                (codes, type) = (AllErrorStatusCodes, "ProblemDetails");
                break;
            case "setAllJsonProblem":
                (codes, type) = (AllErrorStatusCodes, "ApiProblem");
                break;
            case "setAllJsonString" or "setAllTextPlain":
                (codes, type) = (AllErrorStatusCodes, "string");
                break;
            case "setProblemJson":
                (codes, type) = ([400, 404, 409, 422], "ApiProblem");
                break;
            case "setRefResponse":
                (codes, type) = ([404, 422], "RefOnlyError");
                break;
            case "getFault":
                (codes, type) = ([500, 503], "none");
                break;
            case "getDefaultError":
                return null;
            default:
                throw new InvalidOperationException($"The matrix has no declaration rule for '{operationId}'");
        }

        return codes.Contains(status) ? type : null;
    }

    /// <summary>
    /// The statuses the client adds by itself when the specification does not declare them (Working with Error
    /// Responses, "The client adds some statuses by itself"): 400 for operations with parameters, 404 for
    /// GET/PUT/PATCH/DELETE with path parameters, 409 for POST/PUT, 500 and 504 always (no operation here is secured
    /// or rate limited, so 401/403/429 are never added). Every matrix operation has a path parameter.
    /// </summary>
    private static bool IsAddedByClient(
        string operationId,
        int status)
        => DeclaredError(operationId, status) is null &&
           status switch
           {
               400 or 404 or 500 or 504 => true,
               409 => operationId.StartsWith("set", StringComparison.Ordinal),
               _ => false,
           };

    private static bool WritesDefaultBody(ProbeCase probeCase)
        => probeCase.OperationId == "getDefaultError" &&
           (probeCase.Mode == "error" || (probeCase.Mode.StartsWith('d') && probeCase.Mode.Length == 4));

    /// <summary>
    /// The accessor the EndpointPerOperation client must use for an error status (Working with Error Responses,
    /// "C# client"): <c>OnDefault</c> for <c>DefaultErrorContent</c>, else the status's own accessor, and the
    /// type; <see langword="null"/> when the status is neither declared nor added (no typed accessor).
    /// </summary>
    private static (bool OnDefault, string Type)? ExpectedAccessor(
        ProbeCase probeCase,
        int status,
        string format)
    {
        var operationId = probeCase.OperationId;
        if (WritesDefaultBody(probeCase))
        {
            // A status the client adds itself is split by media type - except with Custom, which reads those
            // statuses as the custom model.
            return format == "Custom" && IsAddedByClient(operationId, status)
                ? (false, CustomModel)
                : (true, DefaultModel);
        }

        var declared = DeclaredError(operationId, status);
        if (declared == "none")
        {
            // Nothing declared: errorResponseFormat decides.
            return (false, format switch
            {
                "ProblemDetails" => status == 400 ? "ValidationProblemDetails" : "ProblemDetails",
                "PlainText" => status == 400 ? "ValidationProblemDetails" : "string",
                "PlainTextOnly" => "string",
                "Custom" => CustomModel,
                _ => throw new InvalidOperationException($"Unknown errorResponseFormat '{format}'"),
            });
        }

        if (declared is not null)
        {
            return (false, declared);
        }

        if (IsAddedByClient(operationId, status))
        {
            return (false, format == "Custom" ? CustomModel : status == 400 ? "ValidationProblemDetails" : "ProblemDetails");
        }

        return null;
    }

    /// <summary>
    /// What the body is, read from the bytes and the media type.
    /// </summary>
    private static string BodyKind(WireResult wire)
    {
        if (wire.Body == "(empty)")
        {
            return "empty";
        }

        var media = wire.MediaType.ToLowerInvariant();
        if (media.StartsWith("text/", StringComparison.Ordinal))
        {
            return "raw text";
        }

        if (!IsJsonMedia(media))
        {
            return "other";
        }

        JsonNode? node;
        try
        {
            node = JsonNode.Parse(wire.Body);
        }
        catch (JsonException)
        {
            return "invalid JSON";
        }

        return node switch
        {
            JsonValue value when value.GetValueKind() == JsonValueKind.String => "JSON string",
            JsonObject obj when obj.ContainsKey("errors") && (obj.ContainsKey("title") || obj.ContainsKey("status")) => "ValidationProblemDetails",
            JsonObject obj when media == "application/problem+json" && (obj.ContainsKey("title") || obj.ContainsKey("status")) => "ProblemDetails",
            JsonObject => "JSON object",
            _ => "JSON",
        };
    }

    /// <summary>
    /// A media type the TypeScript clients keep as a string: <c>text/*</c> and XML - as for a success body.
    /// </summary>
    private static bool IsTextMedia(string media)
        => media.StartsWith("text/", StringComparison.Ordinal) || media == "application/xml" || media.EndsWith("+xml", StringComparison.Ordinal);

    private static bool IsJsonMedia(string media)
        => media is "application/json" or "application/problem+json" || media.EndsWith("+json", StringComparison.Ordinal);

    /// <summary>
    /// The server side: the status, media type and body the contract table (Working with Error Responses, "What
    /// the server writes") gives for the case.
    /// </summary>
    private static (string Verdict, string Why) WireVerdict(
        ProbeCase probeCase,
        WireResult wire)
    {
        if (CaseGroup(probeCase) == "sweep")
        {
            var problem = CheckErrorContract(probeCase, wire);
            return problem is null
                ? (VerdictPass, "as the contract table says for this declaration")
                : (VerdictFail, problem);
        }

        var status = ExpectedStatus(probeCase);
        if (wire.Status != status)
        {
            return (VerdictFail, $"expected status {status}");
        }

        if (StubResponses.TryGetValue(probeCase.Mode, out var stub))
        {
            return string.Equals(wire.ContentType, stub.ContentType ?? "(none)", StringComparison.Ordinal) &&
                   string.Equals(wire.Body, stub.Body.Length == 0 ? "(empty)" : stub.Body, StringComparison.Ordinal)
                ? (VerdictPass, "the stub's response - not the generated server")
                : (VerdictFail, "expected the stub's response");
        }

        var body = wire.Body == "(empty)" ? null : TryParseJson(wire.Body);
        var isProblem = string.Equals(wire.MediaType, "application/problem+json", StringComparison.Ordinal);
        var empty = probeCase.Mode.EndsWith("-empty", StringComparison.Ordinal);

        if (probeCase.Reason == TooLongReason)
        {
            return isProblem && body?["errors"]?["reason"] is JsonArray
                ? (VerdictPass, "a ValidationProblemDetails keyed by the wire name")
                : (VerdictFail, "expected a 400 ValidationProblemDetails with the 'reason' key");
        }

        if (probeCase.Mode == "ok")
        {
            return status == 204
                ? wire.Body == "(empty)" ? (VerdictPass, "204, no body") : (VerdictFail, "expected no body")
                : JsonNode.DeepEquals(body, new JsonObject { ["name"] = "thing" }) ? (VerdictPass, "the success body") : (VerdictFail, "expected the success body");
        }

        if (WritesDefaultBody(probeCase))
        {
            var expected = probeCase.Mode == "error"
                ? new JsonObject { ["code"] = "E500", ["message"] = "500 error from handler" }
                : new JsonObject { ["code"] = $"c{status}", ["message"] = $"{status} default from handler" };
            return string.Equals(wire.MediaType, "application/json", StringComparison.Ordinal) && JsonNode.DeepEquals(body, expected)
                ? (VerdictPass, "the default body (application/json) with the handler's status")
                : (VerdictFail, "expected the handler's default body under application/json");
        }

        var problemWithStatus = isProblem && TryReadStatus(wire.Body, out var bodyStatus) && bodyStatus == status;
        if (probeCase.Mode.StartsWith("throw", StringComparison.Ordinal))
        {
            // "no detail for 5xx outside Development" (the host runs as Production).
            if (!problemWithStatus)
            {
                return (VerdictFail, "expected a ProblemDetails with the mapped status");
            }

            return status >= 500 && body?["detail"] is not null
                ? (VerdictFail, "a 5xx ProblemDetails outside Development must have no detail")
                : (VerdictPass, status >= 500 ? "a ProblemDetails with the mapped status, no detail" : "a ProblemDetails with the mapped status");
        }

        // A generated error factory, called with a value or empty.
        var declared = DeclaredError(probeCase.OperationId, status);
        if (!empty && declared is "ApiProblem" or "RefOnlyError")
        {
            var (media, expected) = declared == "ApiProblem"
                ? ("application/problem+json", (JsonNode)new JsonObject { ["type"] = "about:blank", ["title"] = HandlerCall(probeCase).Split('(')[0], ["status"] = status, ["detail"] = $"{status} problem from handler", ["instance"] = "/instance" })
                : ("application/json", new JsonObject { ["code"] = $"E{status}", ["message"] = $"{status} error from handler" });
            return string.Equals(wire.MediaType, media, StringComparison.Ordinal) && JsonNode.DeepEquals(body, expected)
                ? (VerdictPass, $"the declared {declared} under {media}")
                : (VerdictFail, $"expected the handler's {declared} under {media}");
        }

        if (!problemWithStatus)
        {
            return (VerdictFail, "expected a ProblemDetails with the response status");
        }

        if (empty)
        {
            return (VerdictPass, "no body from the handler: the host wiring's ProblemDetails");
        }

        var carriesValue = (((string?)body?["detail"])?.EndsWith(" from handler", StringComparison.Ordinal) ?? false) ||
                           body?["errors"]?["reason"]?[0]?.GetValue<string>() == "reason rejected by handler";
        return carriesValue
            ? (VerdictPass, "a ProblemDetails with the handler's value")
            : (VerdictFail, "the handler's value is missing from the ProblemDetails");
    }

    /// <summary>
    /// The C# EndpointPerOperation client (Working with Error Responses, "C# client"): the accessor the spec gives
    /// the status never throws, and its value is compared field by field with the body on the wire. <c>lossy</c>
    /// names the exact fields of the body the typed value cannot hold; any other difference fails.
    /// </summary>
    private static JsonObject EndpointPerOperationVerdict(
        ProbeCase probeCase,
        WireResult wire,
        string format,
        string[]? row)
    {
        if (row is null)
        {
            return Cell(VerdictFail, "the client produced no result", "(missing)");
        }

        var accessor = row[4];
        var summary = $"{row[1]} · {accessor}";
        if (int.Parse(row[1], CultureInfo.InvariantCulture) != wire.Status)
        {
            return Cell(VerdictFail, $"status {row[1]}, the wire said {wire.Status}", summary);
        }

        if (accessor.Contains(" THROWS ", StringComparison.Ordinal))
        {
            return Cell(VerdictFail, "the typed accessor throws", summary);
        }

        if (wire.Status is >= 200 and < 300)
        {
            var expectedSuccess = wire.Status == 204 ? "IsNoContent (no content property)" : "OkContent => Item {\"Name\":\"thing\"}";
            return row[2] == "True" && accessor == expectedSuccess
                ? Cell(VerdictPass, "IsSuccess, " + expectedSuccess, summary)
                : Cell(VerdictFail, $"expected IsSuccess and '{expectedSuccess}'", summary);
        }

        if (row[2] != "False")
        {
            return Cell(VerdictFail, "IsSuccess should be false for an error status", summary);
        }

        var expected = ExpectedAccessor(probeCase, wire.Status, format);
        var rawBody = wire.Body == "(empty)" ? string.Empty : wire.Body;
        if (expected is null)
        {
            // Neither declared nor added: no typed accessor, the raw body in Content.
            if (accessor != "(none)")
            {
                return Cell(VerdictFail, "an undeclared status should have no typed accessor", summary);
            }

            return row.Length > 5 && string.Equals(WithoutTraceId(row[5]), WithoutTraceId(rawBody), StringComparison.Ordinal)
                ? Cell(VerdictPass, "status not declared: no typed accessor, the raw body in Content", summary)
                : Cell(VerdictFail, "status not declared: Content should be the raw body", summary);
        }

        var (onDefault, expectedType) = expected.Value;
        var arrow = accessor.IndexOf(" => ", StringComparison.Ordinal);
        if (arrow < 0)
        {
            return Cell(VerdictFail, $"expected a typed accessor ({expectedType})", summary);
        }

        var property = accessor[..arrow];
        var shown = accessor[(arrow + 4)..];
        var space = shown.IndexOf(' ', StringComparison.Ordinal);
        var type = space < 0 ? shown : shown[..space];
        var value = space < 0 ? null : JsonNode.Parse(shown[(space + 1)..]);
        if (type == "ErrorResponse" && value is JsonObject model && model.ContainsKey("readableMessage"))
        {
            type = CustomModel;
        }

        if ((property == "DefaultErrorContent") != onDefault)
        {
            return Cell(VerdictFail, onDefault ? "expected IsDefaultError / DefaultErrorContent" : "expected the status's own accessor, not DefaultErrorContent", summary);
        }

        if (!string.Equals(type, expectedType, StringComparison.Ordinal))
        {
            return Cell(VerdictFail, $"expected {expectedType}, got {type}", summary);
        }

        var body = IsJsonMedia(wire.MediaType.ToLowerInvariant()) ? TryParseJson(rawBody) : null;
        var isProblem = string.Equals(wire.MediaType, "application/problem+json", StringComparison.OrdinalIgnoreCase);
        if (expectedType == "string")
        {
            // The body unquoted (a JSON string) or as-is (text); an application/problem+json body is read as a
            // ProblemDetails, and the string is its message: the detail, else the title.
            var expectedText = isProblem
                ? ProblemMessage(rawBody)
                : body is JsonValue text && text.GetValueKind() == JsonValueKind.String ? (string)text! : rawBody;
            if (!string.Equals((string?)value, expectedText, StringComparison.Ordinal))
            {
                return Cell(VerdictFail, $"expected \"{Short(expectedText)}\"", summary);
            }

            return isProblem && body?["errors"] is not null
                ? Cell(VerdictLossy, "a string: the ValidationProblemDetails' title - its field errors are only in Content", summary)
                : Cell(VerdictPass, isProblem ? "the ProblemDetails' message (detail, else title)" : "the body as a string", summary);
        }

        if (value is not JsonObject valueObject)
        {
            return Cell(VerdictFail, $"expected a {expectedType} value", summary);
        }

        if (body is not JsonObject wireObject)
        {
            return NonObjectBody(expectedType, valueObject, wire.Status, rawBody, body, summary);
        }

        return CompareModel(expectedType, valueObject, wireObject, summary);
    }

    /// <summary>
    /// A typed error value against the JSON object on the wire: every field of the value equals the wire's field of
    /// the same name (a missing field is <c>null</c>, the custom model's string properties hold numbers as text), and
    /// fields of the body the type cannot hold are reported by name.
    /// </summary>
    private static JsonObject CompareModel(
        string type,
        JsonObject value,
        JsonObject wire,
        string summary)
    {
        var fields = new Dictionary<string, JsonNode?>(StringComparer.OrdinalIgnoreCase);
        foreach (var (key, node) in value)
        {
            if (key == "Extensions" && node is JsonObject extensions)
            {
                foreach (var (extensionKey, extensionNode) in extensions)
                {
                    fields.TryAdd(extensionKey, extensionNode);
                }

                continue;
            }

            fields[key] = node;
        }

        var wireFields = new Dictionary<string, JsonNode?>(StringComparer.OrdinalIgnoreCase);
        foreach (var (key, node) in wire)
        {
            wireFields[key] = node;
        }

        var lenient = type == CustomModel;
        var differs = fields
            .Where(f => !string.Equals(f.Key, "traceId", StringComparison.OrdinalIgnoreCase))
            .Where(f => !SameValue(f.Key, f.Value, wireFields.GetValueOrDefault(f.Key), lenient))
            .Select(f => f.Key)
            .ToList();
        if (differs.Count > 0)
        {
            return Cell(VerdictFail, $"{type}: {string.Join(", ", differs)} differ from the body", summary);
        }

        if (type == "ProblemDetails" && wire["errors"] is not null)
        {
            return Cell(VerdictLossy, "a ProblemDetails: the field errors are only untyped, in Extensions[\"errors\"]", summary);
        }

        var lost = wire
            .Where(w => w.Key != "traceId" && w.Value is not null && !fields.ContainsKey(w.Key))
            .Select(w => w.Key)
            .ToList();
        return lost.Count > 0
            ? Cell(VerdictLossy, $"{type} has no {string.Join(", ", lost)} - only in Content", summary)
            : Cell(VerdictPass, $"{type}, every field as on the wire", summary);

        static bool SameValue(
            string key,
            JsonNode? actual,
            JsonNode? onWire,
            bool lenient)
        {
            if (JsonNode.DeepEquals(actual, onWire))
            {
                return true;
            }

            // A field the body does not have is null - or the default of a value-type property (an int Status is 0).
            if (onWire is null && actual is JsonValue d &&
                (d.GetValueKind() == JsonValueKind.False || (d.GetValueKind() == JsonValueKind.Number && d.GetValue<decimal>() == 0)))
            {
                return true;
            }

            // A ValidationProblemDetails without errors on the wire has an empty Errors dictionary.
            if (string.Equals(key, "errors", StringComparison.OrdinalIgnoreCase) && onWire is null && actual is JsonObject { Count: 0 })
            {
                return true;
            }

            return lenient && actual is JsonValue a && onWire is JsonValue w &&
                   string.Equals(a.ToString(), w.ToString(), StringComparison.Ordinal);
        }
    }

    /// <summary>
    /// A typed error accessor over a body that is no JSON object (text, a proxy's page, malformed JSON, nothing).
    /// ProblemDetails / ValidationProblemDetails (Working with Error Responses, "C# client"): "a plain-text or
    /// JSON-string body becomes the Detail (unquoted), an empty or whitespace-only body a ProblemDetails with just status
    /// and title".
    /// The custom model has nothing to read: every field is null.
    /// </summary>
    private static JsonObject NonObjectBody(
        string type,
        JsonObject value,
        int status,
        string rawBody,
        JsonNode? parsed,
        string summary)
    {
        if (type is "ProblemDetails" or "ValidationProblemDetails")
        {
            var expectedDetail = string.IsNullOrWhiteSpace(rawBody)
                ? null
                : parsed is JsonValue text && text.GetValueKind() == JsonValueKind.String ? (string)text! : rawBody;
            var fields = value.ToDictionary(f => f.Key, f => f.Value, StringComparer.OrdinalIgnoreCase);
            var statusMatches = fields.GetValueOrDefault("Status") is JsonValue s && s.GetValue<int>() == status;
            var detailMatches = string.Equals((string?)fields.GetValueOrDefault("Detail"), expectedDetail, StringComparison.Ordinal);
            var titled = expectedDetail is not null || fields.GetValueOrDefault("Title") is not null;
            return statusMatches && detailMatches && titled
                ? Cell(VerdictPass, expectedDetail is null ? $"{type} with the status and a title (no body)" : $"{type} with the body as its Detail", summary)
                : Cell(VerdictFail, expectedDetail is null ? $"expected a {type} with the status and a title" : $"expected a {type} with the status and the body as its Detail", summary);
        }

        // The custom model, or a declared model: nothing to read, every field null (Working with Error Responses,
        // "a body that is no JSON object leaves every property null").
        if (type is not "string")
        {
            // Null, or the default of a value-type property (an int Status is 0).
            return value.All(f => f.Value is null ||
                                  (f.Value is JsonValue d && (d.GetValueKind() == JsonValueKind.False || (d.GetValueKind() == JsonValueKind.Number && d.GetValue<decimal>() == 0))))
                ? string.IsNullOrWhiteSpace(rawBody)
                    ? Cell(VerdictPass, "no body: every field null", summary)
                    : Cell(VerdictLossy, "the body is no JSON object: every field null, the body only in Content", summary)
                : Cell(VerdictFail, "the body is no JSON object, yet fields are set", summary);
        }

        return Cell(VerdictFail, $"{type} from a body that is no JSON object", summary);
    }

    private static JsonNode? TryParseJson(string text)
    {
        if (text.Length == 0)
        {
            return null;
        }

        try
        {
            return JsonNode.Parse(text);
        }
        catch (JsonException)
        {
            return null;
        }
    }

    /// <summary>
    /// The C# TypedClient (Working with Error Responses, "TypedClient"): <c>Throw</c> throws
    /// <c>HttpRequestException</c> with the status and the error body; <c>Result</c> returns the status,
    /// <c>IsSuccess</c>, the raw body in <c>Content</c>, and the parsed model only for a success.
    /// </summary>
    private static JsonObject TypedClientVerdict(
        WireResult wire,
        bool throwStyle,
        string[]? row)
    {
        if (row is null)
        {
            return Cell(VerdictFail, "the client produced no result", "(missing)");
        }

        // The traceId differs per request (the wire was captured by its own request).
        var outcome = WithoutTraceId(row[1]);
        var success = wire.Status is >= 200 and < 300;
        var body = WithoutTraceId(wire.Body == "(empty)" ? string.Empty : wire.Body);

        if (throwStyle)
        {
            if (success)
            {
                return outcome == "returned normally"
                    ? Cell(VerdictPass, "returned normally", outcome)
                    : Cell(VerdictFail, "a success status threw", outcome);
            }

            var expectedStart = $"HttpRequestException: HTTP {wire.Status} ";
            if (!outcome.StartsWith(expectedStart, StringComparison.Ordinal))
            {
                return Cell(VerdictFail, $"expected '{expectedStart}…'", outcome);
            }

            return outcome.EndsWith(": " + body, StringComparison.Ordinal) || (body.Length == 0 && outcome.EndsWith("): ", StringComparison.Ordinal))
                ? Cell(VerdictPass, "HttpRequestException with the status and the body", outcome)
                : Cell(VerdictFail, "the exception does not carry the error body", outcome);
        }

        var expected = $"{wire.Status} IsSuccess={success} Content={body} ContentObject={(wire.Status == 200 ? "Item" : "null")}";
        return string.Equals(outcome, expected, StringComparison.Ordinal)
            ? Cell(VerdictPass, success ? "IsSuccess" : "IsSuccess = false, the raw body in Content", outcome)
            : Cell(VerdictFail, "expected the status, IsSuccess, the raw body and the success model", outcome);
    }

    /// <summary>
    /// The named result arm of a status, or <see langword="null"/>.
    /// </summary>
    private static string? NamedArm(int status)
        => status switch
        {
            400 => "badRequest",
            401 => "unauthorized",
            403 => "forbidden",
            404 => "notFound",
            409 => "conflict",
            422 => "unprocessableEntity",
            429 => "tooManyRequests",
            _ => null,
        };

    /// <summary>
    /// The arm the specification gives a status (Working with Error Responses, "Result arms"): its own named arm
    /// when declared, added by the server, or covered by a <c>default</c> (which fans out to the named arms) - 400 is
    /// always <c>badRequest</c> - else <c>clientError</c> / <c>serverError</c>.
    /// </summary>
    private static string ExpectedArm(
        string operationId,
        int status)
    {
        var own = NamedArm(status);
        return own is not null &&
               (status == 400 || DeclaredError(operationId, status) is not null || IsAddedByClient(operationId, status) || operationId == "getDefaultError")
            ? own
            : status < 500 ? "clientError" : "serverError";
    }

    /// <summary>
    /// The TypeScript clients (Working with Error Responses, "TypeScript client"): the arm the specification gives
    /// the status (and the generated union must list exactly the specification's named arms); an <c>ApiError</c>
    /// (<c>ValidationError</c> for 400) whose <c>body</c> is read by the actual Content-Type, whose
    /// <c>type</c>/<c>title</c>/<c>detail</c>/<c>instance</c> are the body's string fields, and whose
    /// <c>message</c> follows the documented precedence (string body, detail, title, message, status text,
    /// <c>HTTP {status}</c>).
    /// </summary>
    private static JsonObject TypeScriptVerdict(
        ProbeCase probeCase,
        WireResult wire,
        JsonObject? result,
        string[] arms)
    {
        if (result is null)
        {
            return Cell(VerdictFail, "the client produced no result", "(missing)");
        }

        var specArms = NamedArmStatuses.Select(s => ExpectedArm(probeCase.OperationId, s)).Where(a => a is not ("clientError" or "serverError")).ToHashSet(StringComparer.Ordinal);
        var generatedArms = arms.Where(a => NamedArmStatuses.Any(s => NamedArm(s) == a)).ToHashSet(StringComparer.Ordinal);
        if (!generatedArms.SetEquals(specArms))
        {
            return Cell(VerdictFail, $"the generated union has the named arms [{string.Join(", ", generatedArms.Order(StringComparer.Ordinal))}], the specification gives [{string.Join(", ", specArms.Order(StringComparer.Ordinal))}]", string.Join(", ", arms));
        }

        if (result["threw"] is { } threw)
        {
            // Node's fetch (undici) rejects every 407 response - reproduced with a plain fetch() call - so no client
            // built on it can see the response.
            return wire.Status == 407 && ((string)threw!).Contains("fetch failed", StringComparison.Ordinal)
                ? Cell(VerdictPlatform, "Node's fetch rejects a 407 response before any client code runs", Short((string)threw!))
                : Cell(VerdictFail, "the client method threw", Short((string)threw!));
        }

        var arm = (string?)result["arm"] ?? "(none)";
        var status = (int?)result["httpStatus"] ?? 0;
        var message = (string?)result["message"];
        var summary = $"{status} · {arm}" + (result["errorClass"] is { } errorClass ? $" · {errorClass}" : string.Empty) +
                      (message is null ? string.Empty : $" · message: {message}");

        if (status != wire.Status)
        {
            return Cell(VerdictFail, $"status {status}, the wire said {wire.Status}", summary);
        }

        if (wire.Status is >= 200 and < 300)
        {
            var expectedSuccessArm = wire.Status == 204 ? "noContent" : "ok";
            return arm == expectedSuccessArm
                ? Cell(VerdictPass, "success arm", summary)
                : Cell(VerdictFail, $"expected arm '{expectedSuccessArm}'", summary);
        }

        var expectedArm = ExpectedArm(probeCase.OperationId, wire.Status);
        if (arm != expectedArm)
        {
            return Cell(VerdictFail, $"expected arm '{expectedArm}'", summary);
        }

        var expectedClass = wire.Status == 400 ? "ValidationError" : "ApiError";
        if (!string.Equals((string?)result["errorClass"], expectedClass, StringComparison.Ordinal))
        {
            return Cell(VerdictFail, $"expected {expectedClass}", summary);
        }

        if ((int?)result["errorStatus"] != wire.Status)
        {
            return Cell(VerdictFail, $"ApiError.status should be {wire.Status}", summary);
        }

        // body: parsed by the actual Content-Type.
        var media = wire.MediaType.ToLowerInvariant();
        var bodyText = wire.Body == "(empty)" ? string.Empty : wire.Body;
        JsonNode? expectedBody = null;
        var bodyDefined = false;
        if (bodyText.Length > 0 && IsJsonMedia(media))
        {
            expectedBody = TryParseJson(bodyText);
            bodyDefined = expectedBody is not null;
        }
        else if (IsTextMedia(media) && bodyText.Length > 0)
        {
            expectedBody = JsonValue.Create(bodyText);
            bodyDefined = true;
        }

        var actualBody = result["body"]?.DeepClone();
        RemoveTraceId(expectedBody);
        RemoveTraceId(actualBody);
        var actualDefined = actualBody is not JsonValue v || v.GetValueKind() != JsonValueKind.String || (string?)v != "__undefined__";
        if (bodyDefined != actualDefined || (bodyDefined && !JsonNode.DeepEquals(expectedBody, actualBody)))
        {
            return Cell(VerdictFail, "body is not the response body read by its Content-Type", summary);
        }

        // type / title / detail / instance: the body's string fields.
        foreach (var (field, recorded) in ((string, string)[])[("type", "problemType"), ("title", "title"), ("detail", "detail"), ("instance", "instance")])
        {
            var expectedField = expectedBody is JsonObject problem && problem[field] is JsonValue fieldValue && fieldValue.GetValueKind() == JsonValueKind.String
                ? (string?)fieldValue
                : null;
            if (!string.Equals((string?)result[recorded], expectedField, StringComparison.Ordinal))
            {
                return Cell(VerdictFail, $"{field} should be {(expectedField is null ? "undefined" : $"'{Short(expectedField)}'")}", summary);
            }
        }

        // message precedence.
        var statusText = (string?)result["statusText"];
        string expectedMessage;
        if (expectedBody is JsonValue s && s.GetValueKind() == JsonValueKind.String && ((string?)s)?.Length > 0)
        {
            expectedMessage = (string)s!;
        }
        else if (expectedBody is JsonObject o && FirstString(o, "detail", "title", "message") is { } fromBody)
        {
            expectedMessage = fromBody;
        }
        else
        {
            expectedMessage = string.IsNullOrEmpty(statusText) ? $"HTTP {wire.Status}" : statusText;
        }

        if (!string.Equals(message, expectedMessage, StringComparison.Ordinal))
        {
            return Cell(VerdictFail, $"message should be '{Short(expectedMessage)}'", summary);
        }

        if (wire.Status == 400)
        {
            var expectedErrors = expectedBody is JsonObject vpd && vpd["errors"] is JsonObject errors ? errors : new JsonObject();
            if (!JsonNode.DeepEquals(expectedErrors, result["errors"]))
            {
                return Cell(VerdictFail, "errors should be the ValidationProblemDetails errors (or {})", summary);
            }
        }

        return Cell(VerdictPass, $"{arm}: {expectedClass}, body, fields and message as documented", summary);

        static string? FirstString(
            JsonObject obj,
            params string[] names)
        {
            foreach (var name in names)
            {
                if (obj[name] is JsonValue value && value.GetValueKind() == JsonValueKind.String && ((string?)value)?.Length > 0)
                {
                    return (string)value!;
                }
            }

            return null;
        }
    }

    private static JsonObject Cell(
        string verdict,
        string why,
        string summary)
        => new()
        {
            ["verdict"] = verdict,
            ["why"] = why,
            ["summary"] = summary,
        };

    private static string MethodKey(ProbeCase probeCase)
        => probeCase.OperationId;

    private static string WithoutTraceId(string text)
        => Regex.Replace(text, @",?""traceId"":""[^""]*""", string.Empty, RegexOptions.None, TimeSpan.FromSeconds(1));

    private static void RemoveTraceId(JsonNode? node)
    {
        if (node is JsonObject obj)
        {
            obj.Remove("traceId");
        }
    }

    private static JsonObject Provenance()
    {
        var root = FindRepositoryRoot();

        // The working tree the run used, without touching it: a stash commit of the tracked changes (empty when
        // there are none), plus the hash of every untracked source and test file - so the code under test is identifiable before a
        // commit exists.
        var untracked = RunTool("git", "ls-files --others --exclude-standard -- src test", root).Output
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Order(StringComparer.Ordinal)
            .ToList();
        var untrackedHashes = new JsonObject();
        foreach (var file in untracked)
        {
            var hashed = RunTool("git", $"hash-object \"{file}\"", root);
            untrackedHashes[file] = GitHash(hashed.Output) ?? $"(no hash: exit {hashed.ExitCode}, {Short(hashed.Output)})";
        }

        var stash = RunTool("git", "stash create", root);
        return new JsonObject
        {
            ["commit"] = RunTool("git", "rev-parse --short HEAD", root).Output.Trim(),
            ["uncommittedFiles"] = RunTool("git", "status --porcelain", root).Output.Split('\n', StringSplitOptions.RemoveEmptyEntries).Length,
            ["workingTreeStash"] = GitHash(stash.Output) ?? $"(no hash: exit {stash.ExitCode}, {Short(stash.Output)})",
            ["untrackedFiles"] = untrackedHashes,
            ["dotnet"] = Environment.Version.ToString(),
            ["node"] = RunTool("node", "--version", root).Output.Trim(),
            ["os"] = System.Runtime.InteropServices.RuntimeInformation.OSDescription,
        };
    }

    // git writes line-ending warnings to stderr, which RunTool merges into the output: keep the hash only.
    private static string? GitHash(string output)
        => Regex.Match(output, @"\b[0-9a-f]{40}\b", RegexOptions.None, TimeSpan.FromSeconds(1)) is { Success: true } match ? match.Value : null;

    /// <summary>
    /// Generates the TypeScript Fetch and Axios clients with the CLI executable, and runs every case through them
    /// against the host.
    /// </summary>
    private static Dictionary<string, (Dictionary<string, JsonObject> Results, Dictionary<string, string[]> Arms)> RunTypeScriptClients(
        Uri baseAddress,
        IReadOnlyList<ProbeCase> cases)
    {
        var work = Path.Combine(Path.GetTempPath(), "atc-errorbody-e2e", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(work);
        try
        {
            var yamlPath = Path.Combine(work, ProjectName + ".yaml");
            File.WriteAllText(yamlPath, Yaml);

            var cli = FindCliExecutable();
            foreach (var client in (string[])["Fetch", "Axios"])
            {
                var output = Path.Combine(work, client.ToLowerInvariant());
                var generate = RunTool(cli, $"generate client-typescript -s \"{yamlPath}\" -o \"{output}\" --client-type {client} --no-strict", work, TimeSpan.FromMinutes(3));
                Assert.True(generate.ExitCode == 0, $"generate client-typescript ({client}) failed:\n{generate.Output}");
            }

            File.WriteAllText(Path.Combine(work, "package.json"), E2EPackageJson);
            File.WriteAllText(Path.Combine(work, "tsconfig.json"), E2ETsConfig);
            File.WriteAllText(Path.Combine(work, "harness.mts"), E2EHarness);
            var caseList = new JsonArray([
                .. cases.Select(c => (JsonNode)new JsonObject
                {
                    ["name"] = c.Name,
                    ["property"] = char.ToLowerInvariant(c.Segment[0]) + c.Segment[1..],
                    ["method"] = c.OperationId,
                    ["mode"] = c.Mode,
                    ["isPut"] = c.IsPut,
                    ["reason"] = c.Reason,
                }),
            ]);
            File.WriteAllText(Path.Combine(work, "cases.json"), new JsonObject { ["baseUrl"] = baseAddress.ToString().TrimEnd('/'), ["cases"] = caseList }.ToJsonString());

            var install = RunTool("npm", "install --no-audit --no-fund --loglevel=error", work, TimeSpan.FromMinutes(5));
            Assert.True(install.ExitCode == 0, $"npm install failed:\n{install.Output}");

            var result = new Dictionary<string, (Dictionary<string, JsonObject>, Dictionary<string, string[]>)>(StringComparer.Ordinal);
            foreach (var client in (string[])["fetch", "axios"])
            {
                var run = RunTool("npx", $"tsx harness.mts {client}", work, TimeSpan.FromMinutes(5));
                Assert.True(run.ExitCode == 0, $"TypeScript {client} harness failed:\n{run.Output}");

                var records = JsonNode.Parse(File.ReadAllText(Path.Combine(work, $"results-{client}.json")))!.AsArray()
                    .Select(n => n!.AsObject())
                    .ToDictionary(o => (string)o["name"]!, StringComparer.Ordinal);
                Assert.True(records.Count == cases.Count, $"TypeScript {client}: {records.Count} results for {cases.Count} cases");

                result["ts-" + client] = (records, ReadArms(Path.Combine(work, client, "client")));
            }

            return result;
        }
        finally
        {
            try
            {
                Directory.Delete(work, recursive: true);
            }
            catch (IOException)
            {
                // node_modules can stay locked for a moment; the temp folder is cleaned up by the OS.
            }
            catch (UnauthorizedAccessException)
            {
                // As above.
            }
        }
    }

    /// <summary>
    /// The result-union arms of each generated client method (<c>arms: [...]</c> in the request call).
    /// </summary>
    private static Dictionary<string, string[]> ReadArms(string clientDirectory)
    {
        var arms = new Dictionary<string, string[]>(StringComparer.Ordinal);
        foreach (var file in Directory.GetFiles(clientDirectory, "*Client.ts"))
        {
            var source = File.ReadAllText(file);
            foreach (Match match in Regex.Matches(source, @"async (?<method>\w+)\((?:(?!async ).)*?arms: \[(?<arms>[^\]]*)\]", RegexOptions.Singleline, TimeSpan.FromSeconds(2)))
            {
                arms[match.Groups["method"].Value] = [.. match.Groups["arms"].Value.Split(',').Select(a => a.Trim().Trim('\''))];
            }
        }

        return arms;
    }

    private static string FindCliExecutable()
    {
        // The test's own build configuration (bin/Debug or bin/Release).
        var configuration = AppContext.BaseDirectory.Contains($"{Path.DirectorySeparatorChar}Release{Path.DirectorySeparatorChar}", StringComparison.Ordinal)
            ? "Release"
            : "Debug";
        var directory = Path.Combine(FindRepositoryRoot(), "src", "Atc.Rest.Api.Generator.Cli", "bin", configuration, "net10.0");
        var exe = Path.Combine(directory, OperatingSystem.IsWindows() ? "atc-rest-api-gen.exe" : "atc-rest-api-gen");
        Assert.True(File.Exists(exe), $"CLI executable not found: {exe} (build the solution in {configuration})");
        return exe;
    }

    private static string FindRepositoryRoot()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null && !Directory.Exists(Path.Combine(directory.FullName, "test", "Scenarios")))
        {
            directory = directory.Parent;
        }

        return directory?.FullName ?? throw new DirectoryNotFoundException("test/Scenarios not found above " + AppContext.BaseDirectory);
    }

    private static bool IsNodeAvailable(out string reason)
    {
        try
        {
            if (RunTool("node", "--version", Path.GetTempPath()).ExitCode == 0 &&
                RunTool("npm", "--version", Path.GetTempPath()).ExitCode == 0)
            {
                reason = string.Empty;
                return true;
            }
        }
        catch (System.ComponentModel.Win32Exception)
        {
            // Not on PATH.
        }

        reason = "Node toolchain (node/npm) not found; the TypeScript clients cannot run.";
        return false;
    }

    private static (int ExitCode, string Output) RunTool(
        string tool,
        string arguments,
        string workingDirectory,
        TimeSpan? timeout = null)
    {
        // npm / npx are .cmd shims on Windows: route them through cmd.exe.
        var isShim = OperatingSystem.IsWindows() && tool is "npm" or "npx";
        var psi = new System.Diagnostics.ProcessStartInfo
        {
            FileName = isShim ? "cmd.exe" : tool,
            Arguments = isShim ? $"/c {tool} {arguments}" : arguments,
            WorkingDirectory = workingDirectory,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
        };

        using var process = new System.Diagnostics.Process { StartInfo = psi };
        var output = new StringBuilder();
        var sync = new Lock();
        process.OutputDataReceived += (_, e) =>
        {
            lock (sync)
            {
                output.AppendLine(e.Data);
            }
        };
        process.ErrorDataReceived += (_, e) =>
        {
            lock (sync)
            {
                output.AppendLine(e.Data);
            }
        };

        process.Start();
        process.BeginOutputReadLine();
        process.BeginErrorReadLine();
        if (!process.WaitForExit((int)(timeout ?? TimeSpan.FromMinutes(1)).TotalMilliseconds))
        {
            process.Kill(entireProcessTree: true);
            return (-1, $"Timed out: {tool} {arguments}");
        }

        process.WaitForExit();
        lock (sync)
        {
            return (process.ExitCode, output.ToString());
        }
    }

    private const string E2EPackageJson = """
        {
          "name": "atc-errorbody-e2e",
          "version": "0.0.0",
          "private": true,
          "type": "module",
          "dependencies": {
            "axios": "^1.7.0"
          },
          "devDependencies": {
            "tsx": "^4.19.0",
            "typescript": "^5.6.0"
          }
        }
        """;

    private const string E2ETsConfig = """
        {
          "compilerOptions": {
            "target": "ES2022",
            "lib": ["ES2022", "DOM"],
            "module": "ESNext",
            "moduleResolution": "bundler",
            "strict": true,
            "esModuleInterop": true,
            "skipLibCheck": true,
            "noEmit": true
          }
        }
        """;

    // Calls every case through the generated ApiService against the live host and records what the client exposes.
    private const string E2EHarness = """
        import { readFileSync, writeFileSync } from 'node:fs';

        const which = process.argv[2];
        const { baseUrl, cases } = JSON.parse(readFileSync('cases.json', 'utf8'));
        const { ApiService } = await import(`./${which}/client/ApiService.ts`);
        const api: any = new ApiService(baseUrl);

        const results: Record<string, unknown>[] = [];
        for (const c of cases) {
          const record: Record<string, unknown> = { name: c.name };
          try {
            const client = api[c.property];
            const r = c.isPut
              ? await client[c.method](c.mode, { reason: c.reason })
              : await client[c.method](c.mode);
            const res = r.response;
            const headers = res?.headers;
            record.arm = r.status;
            record.httpStatus = res?.status;
            record.statusText = res?.statusText ?? null;
            record.contentType = typeof headers?.get === 'function' ? headers.get('content-type') : headers?.['content-type'] ?? null;
            if ('error' in r && r.error) {
              const e = r.error;
              record.errorClass = e.constructor?.name ?? null;
              record.errorStatus = e.status ?? null;
              record.message = e.message ?? null;
              record.detail = e.detail ?? null;
              record.title = e.title ?? null;
              record.problemType = e.type ?? null;
              record.instance = e.instance ?? null;
              record.body = e.body === undefined ? '__undefined__' : e.body;
              record.errors = e.errors ?? null;
            }
          } catch (err: any) {
            record.threw = String(err?.stack ?? err);
          }
          results.push(record);
        }

        writeFileSync(`results-${which}.json`, JSON.stringify(results));
        """;
}